parser.script:
// 剧果 JSON API：全部请求需访客 Bearer 令牌（先 POST /auth/guest 换取）。
// 真机 QuickJS 无法 await Promise，故全部走 meta 两跳协议：
//   入口(拼路径) → POST /auth/guest(hjAfterGuest 取 token) → GET 数据(hjData 解析)。
// 同一脚本内顶层 var 在同一引擎生命周期内跨跳共享（HJ_TOKEN/HJ_PATH/HJ_KIND）。
var HJ_API = 'https://api.huangju.net';
var HJ_SITE = 'https://huangju.net';
var HJ_UA = 'Mozilla/5.0 (Linux; Android 11; Pixel 5) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/90.0.4430.91 Mobile Safari/537.36';
var HJ_TOKEN = '';
var HJ_PATH = '';
var HJ_KIND = 'list';

function hjUuid() {
  var s = '';
  for (var i = 0; i < 32; i++) s += Math.floor(Math.random() * 16).toString(16);
  return s.slice(0, 8) + '-' + s.slice(8, 12) + '-4' + s.slice(13, 16) + '-8' + s.slice(17, 20) + '-' + s.slice(20, 32);
}
function hjPayload(v) {
  if (v && typeof v === 'object' && v.data != null && !v.items && !v.url) return v.data;
  return v;
}
function hjValidId(s) {
  return /^[A-Za-z0-9_-]{1,450}$/.test(s);
}
function hjStatus(v) {
  v = String(v == null ? '' : v);
  if (v === 'completed') return 'finished';
  if (v === 'ongoing') return 'ongoing';
  return '';
}
function hjTags(row) {
  var tags = [];
  var seen = {};
  var push = function (t) {
    t = String(t == null ? '' : t).trim();
    if (t && t.length <= 48 && !seen[t] && tags.length < 24) { seen[t] = 1; tags.push(t); }
  };
  var ts = row.tags;
  if (ts && ts.length) {
    for (var i = 0; i < ts.length && i < 24; i++) {
      var t = ts[i];
      push(typeof t === 'object' && t ? (t.name || t.title || '') : t);
    }
  }
  var c0 = row.category;
  if (c0) push(typeof c0 === 'object' && c0 ? c0.name : c0);
  var cs = row.categories;
  if (cs && cs.length) {
    for (var i = 0; i < cs.length && i < 24; i++) {
      var c = cs[i];
      push(typeof c === 'object' && c ? c.name : c);
    }
  }
  if (row.region) push(row.region);
  var y = parseInt(row.year, 10);
  if (y >= 1000 && y <= 9999) push(y + '年');
  var sc = parseFloat(row.score);
  if (sc > 0 && sc <= 10) push('评分 ' + row.score);
  return tags;
}
function hjItem(row) {
  row = row || {};
  var id = String(row.id == null ? '' : row.id);
  var title = String(row.title == null ? '' : row.title).trim();
  if (!hjValidId(id) || !title) return {};
  var slug = String(row.slug == null ? '' : row.slug);
  var full = slug ? slug + '-' + id : id;
  if (!hjValidId(full)) return {};
  var m = { id: full, title: title };
  if (row.coverUrl) m.cover = String(row.coverUrl);
  if (row.description) m.description = String(row.description);
  var tags = hjTags(row);
  if (tags.length) m.tags = tags;
  var st = hjStatus(row.status);
  if (st) m.status = st;
  return m;
}
function hjAuthHeaders() {
  return {
    'Authorization': 'Bearer ' + HJ_TOKEN,
    'Referer': HJ_SITE + '/',
    'Origin': HJ_SITE,
    'User-Agent': HJ_UA
  };
}
function hjGuestMeta() {
  return {
    __meta: true,
    __fetchMethod: 'post',
    __fetchUrl: HJ_API + '/auth/guest',
    __fetchBody: JSON.stringify({ deviceId: hjUuid() }),
    __fetchHeaders: {
      'Content-Type': 'application/json',
      'Referer': HJ_SITE + '/',
      'Origin': HJ_SITE,
      'User-Agent': HJ_UA
    },
    __processor: 'hjAfterGuest'
  };
}
function hjListEntry(raw, context) {
  context = context || {};
  var page = parseInt(context.page, 10);
  if (!page || page < 1) page = 1;
  var qs = '?page=' + page;
  var cat = String(context.category || '');
  var kw = String(context.keyword || '').trim();
  if (kw) {
    qs += '&q=' + encodeURIComponent(kw);
  } else if (cat === '@new') {
    qs += '&sort=new';
  } else if (!cat || cat === 'all') {
    qs += '&sort=hot';
  } else {
    qs += '&category=' + encodeURIComponent(cat);
  }
  HJ_PATH = '/dramas' + qs;
  HJ_KIND = 'list';
  return hjGuestMeta();
}
function hjAfterGuest(pair, context) {
  var resp = (pair && pair.length) ? pair[0] : pair;
  var row = hjPayload(resp) || {};
  var token = String(row.token || '');
  if (!token && row.data && typeof row.data === 'object') token = String(row.data.token || '');
  if (!token || token.length > 8192) return [];
  HJ_TOKEN = token;
  return {
    __meta: true,
    __fetchUrl: HJ_API + HJ_PATH,
    __fetchHeaders: hjAuthHeaders(),
    __processor: 'hjData'
  };
}
function hjCookieFrom(headers) {
  if (!headers) return '';
  var raw = '';
  for (var k in headers) {
    if (String(k).toLowerCase() === 'set-cookie') {
      raw += (raw ? '\n' : '') + String(headers[k]);
    }
  }
  if (!raw) return '';
  var names = ['CloudFront-Policy', 'CloudFront-Signature', 'CloudFront-Key-Pair-Id'];
  var parts = [];
  for (var i = 0; i < names.length; i++) {
    var re = new RegExp('(?:^|[,;\\s])' + names[i] + '\\s*=\\s*([^;,\\s"\' ]+)');
    var m = raw.match(re);
    if (!m) return '';
    parts.push(names[i] + '=' + m[1]);
  }
  return parts.join('; ');
}
function hjEpisodes(row) {
  var eps = row.episodes;
  if (!eps || !eps.length) return [];
  var chapters = [];
  var seenId = {};
  var seenNo = {};
  for (var i = 0; i < eps.length; i++) {
    var ep = eps[i] || {};
    if (ep.playable === false) continue;
    var epId = String(ep.id == null ? '' : ep.id);
    if (!epId || epId.length > 450 || seenId[epId]) continue;
    seenId[epId] = 1;
    var no = parseInt(ep.epNo, 10);
    if (!no || no < 0) no = i + 1;
    if (seenNo[no]) continue;
    seenNo[no] = 1;
    chapters.push({ id: epId, title: '第 ' + no + ' 集', url: '/play/' + epId, number: no });
  }
  return chapters;
}
// 数据跳处理器：入参形态归一（新引擎逐参 / 旧引擎打包数组）。
function hjData(pair, headersArg, context) {
  // 形态归一：新引擎逐参 (响应体, 响应头, context)；旧引擎把 [响应体, 响应头]
  // 打包成数组作首参（此时 context 已是二参）。两种形态都取得到响应头。
  var resp = (pair && pair.length && typeof pair !== 'string') ? pair[0] : pair;
  var headers = (Array.isArray(pair) && pair.length > 1) ? pair[1] : (headersArg || null);
  var row = hjPayload(resp);
  if (!row || typeof row !== 'object') return [];
  if (HJ_KIND === 'video') {
    var addr = String(row.url || '');
    if (addr.indexOf('http://') !== 0 && addr.indexOf('https://') !== 0) return { url: '' };
    var out = { url: addr };
    if (addr.toLowerCase().indexOf('.m3u8') >= 0) out.type = 'm3u8';
    var h = { 'Referer': HJ_SITE + '/', 'User-Agent': HJ_UA };
    var cookie = hjCookieFrom(headers);
    if (cookie) h['Cookie'] = cookie;
    out.headers = h;
    return out;
  }
  if (HJ_KIND === 'detail') {
    return hjItem(row);
  }
  if (HJ_KIND === 'episodes') {
    return hjEpisodes(row);
  }
  if (HJ_KIND === 'categories') {
    var rows = hjPayload(resp);
    if (!rows || !rows.length) return [];
    var out = [{ id: 'all', title: '全部' }, { id: '@new', title: '最新' }];
    for (var i = 0; i < rows.length && i < 300; i++) {
      var c = rows[i] || {};
      var slug = String(c.slug == null ? '' : c.slug);
      var name = String(c.name == null ? '' : c.name).trim();
      if (slug === 'hot' || slug === 'all' || slug === '@new') continue;
      if (!hjValidId(slug) || !name || name.length > 48) continue;
      out.push({ id: slug, title: name });
    }
    return out;
  }
  var items = row.items;
  var out = [];
  if (items && items.length) {
    for (var i = 0; i < items.length; i++) {
      var m = hjItem(items[i]);
      if (m.id) out.push(m);
    }
  }
  return out;
}
function parseLatest(raw, context) { return hjListEntry(raw, context); }
function parseSearch(raw, context) { return hjListEntry(raw, context); }
function parseCategory(raw, context) { return hjListEntry(raw, context); }
function parseCategories(raw, context) {
  HJ_PATH = '/categories';
  HJ_KIND = 'categories';
  return hjGuestMeta();
}
function parseDetail(raw, context) {
  context = context || {};
  var id = String(context.id || '').trim();
  if (!hjValidId(id)) return [];
  HJ_PATH = '/dramas/' + encodeURIComponent(id);
  HJ_KIND = 'detail';
  return hjGuestMeta();
}
function parseEpisodes(raw, context) {
  context = context || {};
  var id = String(context.id || '').trim();
  if (!hjValidId(id)) return [];
  HJ_PATH = '/dramas/' + encodeURIComponent(id);
  HJ_KIND = 'episodes';
  return hjGuestMeta();
}
function parseVideo(raw, context) {
  context = context || {};
  var u = String(context.url || '');
  var epId = u;
  var p = u.indexOf('/play/');
  if (p >= 0) epId = u.slice(p + 6);
  var slash = epId.indexOf('/');
  if (slash >= 0) epId = epId.slice(0, slash);
  epId = epId.trim();
  if (!hjValidId(epId)) return [];
  HJ_PATH = '/play/' + encodeURIComponent(epId);
  HJ_KIND = 'video';
  return hjGuestMeta();
}
